  ('b1acf0ea-552a-5338-8a4b-f42cf18d107b'::uuid,'c269b5ca-37ac-5e0a-a17d-caf25eafbaef'::uuid,'accepted',TIMESTAMPTZ '2026-06-02 03:33:02+00')
),
insertable AS (
  SELECT p.* FROM payload p
  WHERE NOT EXISTS (SELECT 1 FROM public.connections c
                    WHERE c.requester_uuid=p.requester_uuid AND c.addressee_uuid=p.addressee_uuid)
    AND NOT EXISTS (SELECT 1 FROM public.connections c
                    WHERE c.requester_uuid=p.addressee_uuid AND c.addressee_uuid=p.requester_uuid)
),
ian AS (SELECT u.uuid FROM public.users u JOIN public.wp_user_bridge b ON b.user_id=u.id WHERE b.wp_user_id=1)
SELECT 'rows in this restore'            AS what, (SELECT count(*) FROM payload)::text AS n
UNION ALL SELECT 'WILL INSERT (after guards)',  (SELECT count(*) FROM insertable)::text
UNION ALL SELECT '  of which accepted',         (SELECT count(*) FROM insertable WHERE status='accepted')::text
UNION ALL SELECT '  of which pending',          (SELECT count(*) FROM insertable WHERE status='pending')::text
UNION ALL SELECT 'already present (skipped)',   ((SELECT count(*) FROM payload)-(SELECT count(*) FROM insertable))::text
UNION ALL SELECT 'members affected',            (SELECT count(DISTINCT x) FROM (SELECT requester_uuid x FROM insertable UNION SELECT addressee_uuid FROM insertable) t)::text
UNION ALL SELECT '--- Ian (WP user 1, via bridge) ---', ''
UNION ALL SELECT 'Ian accepted now',   (SELECT count(*) FROM public.connections c WHERE c.status='accepted' AND (c.requester_uuid=(SELECT uuid FROM ian) OR c.addressee_uuid=(SELECT uuid FROM ian)))::text
UNION ALL SELECT 'Ian pending now',    (SELECT count(*) FROM public.connections c WHERE c.status='pending'  AND (c.requester_uuid=(SELECT uuid FROM ian) OR c.addressee_uuid=(SELECT uuid FROM ian)))::text
UNION ALL SELECT 'Ian rows to restore',(SELECT count(*) FROM insertable i WHERE i.requester_uuid=(SELECT uuid FROM ian) OR i.addressee_uuid=(SELECT uuid FROM ian))::text;
